  let p = base[k];
  let h = 0.52;
  const a = A[k];
  if (a && a.h1 && a.h1.length > 12 && a.daily && a.daily.length) {
    const bars = a.h1;
    const r1h = bars[bars.length-1][1] / bars[bars.length-13][1] - 1;
    h = lib.clamp(0.52 + r1h * 2, 0.45, 0.55);
    const gap = bars[bars.length-1][1] / a.daily[a.daily.length-1][1] - 1;
    p += lib.clamp(gap * 4, -0.06, 0.06);
  }
  const y = cr['US 10Y yield'];
  const g = cr['Henry Hub natural gas futures'];
  const n = cr['Nikkei 225'];
  if (k === 'tlt' && y && y.length > 1) { p += lib.clamp(-(y[y.length-1][1]/y[y.length-2][1]-1) * 1.5, -0.05, 0.05); }
  if (k === 'boil' && g && g.length > 1) { p += lib.clamp((g[g.length-1][1]/g[g.length-2][1]-1) * 1.2, -0.05, 0.05); }
  if (k === 'kospi' && n && n.length > 1) { p += lib.clamp((n[n.length-1][1]/n[n.length-2][1]-1) * 0.8, -0.04, 0.04); }
  out[k] = { h1: Math.round(h*1000)/1000, close: Math.round(lib.clamp(p,0.30,0.70)*1000)/1000 };
}
return out;
